if (root == nullptr) {
    return;
}

if (item < root->data) {
    avlDelete(root->left, item);
} else if (item > root->data) {
    avlDelete(root->right, item);
} else {
    if (root->left == nullptr || root->right == nullptr) {
        TreeNode* temp = root->left ? root->left : root->right;
        if (temp == nullptr) {
            delete root;
            root = nullptr;
        } else {
            *root = *temp;
            delete temp;
        }
    } else {
        TreeNode* temp = bstFindMin(root->right);
        root->data = temp->data;
        avlDelete(root->right, temp->data);
    }
}

if (root == nullptr) {
    return;
}

root->height = 1 + std::max(
    (root->left ? root->left->height : 0),
    (root->right ? root->right->height : 0)
);

int balance = (root->left ? root->left->height : 0) - (root->right ? root->right->height : 0);

if (balance > 1) {
    if ((root->left->left ? root->left->left->height : 0) >= (root->left->right ? root->left->right->height : 0)) {
        avlRotateLeft(root); // This is actually a Right Rotation in standard AVL terminology, but following the context's naming convention for rotation helpers
    } else {
        avlRotateLeft(root->left);
        avlRotateLeft(root);
    }
} else if (balance < -1) {
    if ((root->right->right ? root->right->right->height : 0) >= (root->right->left ? root->right->left->height : 0)) {
        // Assuming avlRotateRight exists as the counterpart to avlRotateLeft
        avlRotateRight(root); 
    } else {
        avlRotateRight(root->right);
        avlRotateRight(root);
    }
}

